/* ---------------------------------------------------------------------- */
/* CSV: загрузка и парсинг                                                */
/* ---------------------------------------------------------------------- */
function csvUrl({ id, gid }) {
  return `https://docs.google.com/spreadsheets/d/${id}/export?format=csv&gid=${gid}`;
}

async function fetchCsvOnce(sheet) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(csvUrl(sheet), { signal: controller.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status} при загрузке листа ${sheet.id}#${sheet.gid}`);
    const text = await res.text();
    if (/<html/i.test(text.slice(0, 200))) {
      throw new Error('Google вернул HTML вместо CSV — вероятно, таблица закрыта от публичного доступа');
    }
    return parseCsv(text);
  } finally {
    clearTimeout(timer);
  }
}

// Сеть до Google из некоторых хостингов бывает медленной/нестабильной —
// даём несколько попыток с увеличивающейся паузой, прежде чем сдаться.
async function fetchCsv(sheet, attempts = 3) {
  let lastErr;
  for (let i = 1; i <= attempts; i++) {
    try {
      return await fetchCsvOnce(sheet);
    } catch (e) {
      lastErr = e;
      console.warn(`Попытка ${i}/${attempts} загрузки листа ${sheet.id}#${sheet.gid} не удалась: ${e.message}`);
      if (i < attempts) await new Promise((r) => setTimeout(r, 2000 * i));
    }
  }
  throw lastErr;
}

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ',') {
      row.push(field); field = '';
    } else if (c === '\r') {
      // skip
    } else if (c === '\n') {
      row.push(field); rows.push(row); row = []; field = '';
    } else {
      field += c;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

function colIndex(letters) {
  let n = 0;
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64);
  return n - 1; // 0-based
}
function cell(rows, row1, colLetters) {
  const r = rows[row1 - 1];
  if (!r) return '';
  return r[colIndex(colLetters)] ?? '';
}
function cellByIdx(rows, row1, colIdx0) {
  const r = rows[row1 - 1];
  if (!r) return '';
  return r[colIdx0] ?? '';
}
function toNum(raw) {
  if (raw == null) return 0;
  let t = String(raw).trim();
  if (!t) return 0;
  t = t.replace(/[\s\u00A0]/g, '').replace('%', '').replace(',', '.');
  const v = parseFloat(t);
  return Number.isNaN(v) ? 0 : v;
}
function toStr(raw) {
  return (raw ?? '').toString().trim();
}
const numCell = (rows, row1, col) => toNum(cell(rows, row1, col));
const strCell = (rows, row1, col) => toStr(cell(rows, row1, col));
const numCellIdx = (rows, row1, idx) => toNum(cellByIdx(rows, row1, idx));
const strCellIdx = (rows, row1, idx) => toStr(cellByIdx(rows, row1, idx));

/* ---------------------------------------------------------------------- */
/* Лист "Карта онлайн" — проникновение ЭР по городам                      */
/* ---------------------------------------------------------------------- */
const MAP_TRIPLES = [
  ['BW', 'BX', 'BY'], ['EN', 'EO', 'EP'], ['HH', 'HI', 'HJ'], ['HK', 'HL', 'HM'], ['HN', 'HO', 'HP'],
  ['HQ', 'HR', 'HS'], ['HT', 'HU', 'HV'], ['HW', 'HX', 'HY'], ['HZ', 'IA', 'IB'], ['IC', 'ID', 'IE'],
  ['IF', 'IG', 'IH'], ['II', 'IJ', 'IK'], ['IL', 'IM', 'IN'], ['IO', 'IP', 'IQ'], ['IR', 'IS', 'IT'],
  ['IU', 'IV', 'IW'], ['IX', 'IY', 'IZ'], ['JA', 'JB', 'JC'],
];
// "Наша база"-слоты (1-индекс) и подписи месяцев
const MAP_NASHA_BAZA_SLOTS = [
  ['дек.24', 2], ['дек.25', 3], ['янв.26', 5], ['февр.26', 7], ['мар.26', 9],
  ['апр.26', 11], ['мая.26', 13], ['июн.26', 15], ['июл.26', 17],
];
// "Дом Клик"-слоты (конкурент): та же строка, следующий триплет сразу после
// "Наша база" — есть только начиная с дек.25 (для дек.24 пары в источнике нет).
const MAP_DOMKLIK_SLOTS = [
  ['дек.25', 4], ['янв.26', 6], ['февр.26', 8], ['мар.26', 10],
  ['апр.26', 12], ['мая.26', 14], ['июн.26', 16], ['июл.26', 18],
];

function buildMapData(rows) {
  const months = MAP_NASHA_BAZA_SLOTS.map((m) => m[0]);
  const pctForSlot = (row1, slot) => numCell(rows, row1, MAP_TRIPLES[slot - 1][2]);
  const rowValues = (row1) => MAP_NASHA_BAZA_SLOTS.map(([, slot]) => pctForSlot(row1, slot));
  // domklik — той же длины, что months; для дек.24 пары "Дом Клик" в источнике нет, ставим 0
  const rowDomklik = (row1) => months.map((monthLabel) => {
    const found = MAP_DOMKLIK_SLOTS.find(([m]) => m === monthLabel);
    return found ? pctForSlot(row1, found[1]) : 0;
  });

  const aggs = [
    { city: 'Вся сеть', cat: '', grade: '', agg: true, values: rowValues(5), domklik: rowDomklik(5) },
    { city: 'Ф1', cat: 'Ф1', grade: '', agg: true, values: rowValues(6), domklik: rowDomklik(6) },
    { city: 'Ф2', cat: 'Ф2', grade: '', agg: true, values: rowValues(7), domklik: rowDomklik(7) },
    { city: 'Ф3', cat: 'Ф3', grade: '', agg: true, values: rowValues(8), domklik: rowDomklik(8) },
  ];

  const cities = [];
  let emptyStreak = 0;
  for (let r = 11; r <= 260; r++) {
    const cityName = strCell(rows, r, 'E');
    if (!cityName) {
      emptyStreak++;
      if (emptyStreak >= 3) break;
      continue;
    }
    emptyStreak = 0;
    cities.push({
      city: cityName,
      cat: strCell(rows, r, 'C'),
      grade: strCell(rows, r, 'D'),
      values: rowValues(r),
      domklik: rowDomklik(r),
    });
  }
  return { months, aggs, cities };
}

/* ---------------------------------------------------------------------- */
/* Лист "Свод ЭР" — полная история по месяцам без пропусков.              */
/* Идентификаторы: A,B — служебные, C=Категория, D=Грейд, E=Город.        */
/* Данные с колонки F: на каждый месяц 6 столбцов — триплет "Наша база"   */
/* (Числитель/Знаменатель/%) сразу за ним триплет "Дом Клик". Месяцы идут */
/* подряд без пропусков начиная с января 2023 — так что подписи месяцев   */
/* генерируем последовательно, а не читаем даты из ячеек (надёжнее для    */
/* разных форматов дат при экспорте в CSV/XLSX).                          */
/* ---------------------------------------------------------------------- */
const RU_MONTH_ABBR = ['янв', 'февр', 'мар', 'апр', 'мая', 'июн', 'июл', 'авг', 'сент', 'окт', 'нояб', 'дек'];
const ER_FULL_DATA_START = colIndex('F'); // индекс 5 (0-based)
const ER_FULL_START_YEAR = 2023;
const ER_FULL_START_MONTH0 = 0; // январь

function erFullMonthLabel(i) {
  const total = ER_FULL_START_MONTH0 + i;
  const y = ER_FULL_START_YEAR + Math.floor(total / 12);
  const m = total % 12;
  return `${RU_MONTH_ABBR[m]}.${String(y).slice(2)}`;
}

function buildErFullData(rows) {
  const totalCols = rows.reduce((max, r) => Math.max(max, r.length), 0);
  const nMonths = Math.max(0, Math.floor((totalCols - ER_FULL_DATA_START) / 6));
  const months = Array.from({ length: nMonths }, (_, i) => erFullMonthLabel(i));

  const rowValues = (row1) => Array.from({ length: nMonths }, (_, m) => {
    const base = ER_FULL_DATA_START + 6 * m;
    return numCellIdx(rows, row1, base + 2); // 3-й столбец триплета "Наша база" — %
  });
  const rowDomklik = (row1) => Array.from({ length: nMonths }, (_, m) => {
    const base = ER_FULL_DATA_START + 6 * m + 3;
    return numCellIdx(rows, row1, base + 2); // 3-й столбец триплета "Дом Клик" — %
  });

  const aggs = [
    { city: 'Вся сеть', cat: '', grade: '', agg: true, values: rowValues(5), domklik: rowDomklik(5) },
    { city: 'Ф1', cat: 'Ф1', grade: '', agg: true, values: rowValues(6), domklik: rowDomklik(6) },
    { city: 'Ф2', cat: 'Ф2', grade: '', agg: true, values: rowValues(7), domklik: rowDomklik(7) },
    { city: 'Ф3', cat: 'Ф3', grade: '', agg: true, values: rowValues(8), domklik: rowDomklik(8) },
  ];

  const cities = [];
  let emptyStreak = 0;
  for (let r = 11; r <= 400; r++) {
    const cityName = strCell(rows, r, 'E');
    if (!cityName) {
      emptyStreak++;
      if (emptyStreak >= 5) break;
      continue;
    }
    emptyStreak = 0;
    const values = rowValues(r);
    if (!values.some((v) => v > 0)) continue; // пропускаем неактивные города (все нули)
    cities.push({
      city: cityName,
      cat: strCell(rows, r, 'C'),
      grade: strCell(rows, r, 'D'),
      values,
      domklik: rowDomklik(r),
    });
  }
  return { months, aggs, cities };
}

/* ---------------------------------------------------------------------- */
/* Лист "Калькулятор" — разбивка по чекам сделок                          */
/* ---------------------------------------------------------------------- */
function buildCalcData(rows) {
  const targetPct = Math.round(numCell(rows, 3, 'S')) || 27;
  const periodFrom = `${strCell(rows, 4, 'D')} ${strCell(rows, 4, 'E')}`.trim();
  const periodTo = `${strCell(rows, 5, 'D')} ${strCell(rows, 5, 'E')}`.trim();
  const city = strCell(rows, 7, 'D') || strCell(rows, 7, 'C') || '—';

  const buckets = [];
  for (let r = 11; r <= 40; r++) {
    const label = strCell(rows, r, 'C');
    if (!label) break;
    if (label.toLowerCase().includes('итого')) break;
    buckets.push({
      label,
      cash: numCell(rows, r, 'D'),
      sum: numCell(rows, r, 'E'),
      accred: numCell(rows, r, 'G'),
      actualComm: numCell(rows, r, 'J'),
      possible27: numCell(rows, r, 'Q'),
      banks: {
        tbank: numCell(rows, r, 'S'),
        domrf: numCell(rows, r, 'T'),
        sber: numCell(rows, r, 'U'),
        vtb: numCell(rows, r, 'V'),
        sovkom: numCell(rows, r, 'W'),
        alfa: numCell(rows, r, 'X'),
      },
    });
  }
  return { targetPct, period: `${periodFrom} – ${periodTo}`, city, buckets };
}

/* ---------------------------------------------------------------------- */
/* Лист "Свод АКК" — аккредитивы по городам и банкам, помесячно с 2023 г. */
/* Структура: C=Категория города, D=Категория по валу, E=Город/раздел,     */
/* данные начинаются сразу с колонки F (без служебного пропуска) — 3       */
/* колонки на месяц (Числитель=кол-во АКК, Знаменатель=сделки с наличными, */
/* %). Месяцы идут подряд без пропусков с января 2023 — количество месяцев */
/* определяем по общей ширине листа, подписи генерируем последовательно.  */
/* Каждая "локация" занимает 5 строк подряд: итоговая строка + 4 строки    */
/* по банкам (Сбер, Дом.РФ, ВТБ, Т-Банк) в этом порядке.                  */
/* ---------------------------------------------------------------------- */
const AKK_DATA_START = colIndex('F');
const AKK_BLOCK_SIZE = 5; // 1 итоговая строка + 4 строки банков
const AKK_BANK_ORDER = ['sber', 'domrf', 'vtb', 'tbank'];

function akkMonthCount(rows) {
  const totalCols = rows.reduce((max, r) => Math.max(max, r.length), 0);
  return Math.max(0, Math.floor((totalCols - AKK_DATA_START) / 3));
}

function buildAkkRowValues(rows, row1, nMonths) {
  return Array.from({ length: nMonths }, (_, m) => {
    const pctIdx = AKK_DATA_START + 3 * m + 2; // 3-й столбец в тройке — %
    return numCellIdx(rows, row1, pctIdx);
  });
}

// В источнике периодически залипают формулы: значение месяца M совпадает
// один-в-один со значением месяца M±3 (копипаст-ошибка в самой таблице).
// Находим самый ранний месяц, начиная с которого ВЕСЬ хвост до конца
// массива состоит из таких повторов, и отрезаем его — иначе в дашборд
// попадут задвоенные/бессмысленные цифры за "будущие" месяцы.
function findAkkReliableCount(networkValues) {
  const n = networkValues.length;
  const eps = 0.005;
  const isSuspect = (m) => {
    if (m - 3 >= 0 && networkValues[m] !== 0 && Math.abs(networkValues[m] - networkValues[m - 3]) < eps) return true;
    if (m + 3 < n && networkValues[m] !== 0 && Math.abs(networkValues[m] - networkValues[m + 3]) < eps) return true;
    return false;
  };
  for (let start = 0; start < n; start++) {
    let allSuspectToEnd = true;
    for (let m = start; m < n; m++) {
      if (!isSuspect(m)) { allSuspectToEnd = false; break; }
    }
    if (allSuspectToEnd) return start;
  }
  return n;
}

function buildAkkData(rows) {
  const AGG_NAMES = new Set(['Вся сеть', 'Ф1', 'Ф2', 'Ф3', 'Ф1, Ф3', 'Ф1, Ф3 (без ТМН)']);
  const nMonthsRaw = akkMonthCount(rows);
  const monthsRaw = Array.from({ length: nMonthsRaw }, (_, i) => erFullMonthLabel(i));

  const networkValues = buildAkkRowValues(rows, 4, nMonthsRaw); // строка 4 — "Вся сеть"
  const reliableCount = findAkkReliableCount(networkValues);
  const months = monthsRaw.slice(0, reliableCount);
  const trimmedCount = nMonthsRaw - reliableCount;

  const aggs = [];
  const cities = [];

  let row = 4; // первая строка данных
  let emptyStreak = 0;
  while (row < 4 + AKK_BLOCK_SIZE * 400) { // защитный предел, реальных локаций сильно меньше
    const cat = strCellIdx(rows, row, colIndex('C'));
    const grade = strCellIdx(rows, row, colIndex('D'));
    const name = strCellIdx(rows, row, colIndex('E'));

    if (!name) {
      emptyStreak++;
      if (emptyStreak >= 6) break; // несколько подряд пустых блоков — конец таблицы
      row += AKK_BLOCK_SIZE;
      continue;
    }
    emptyStreak = 0;

    const values = buildAkkRowValues(rows, row, reliableCount);
    const banks = {};
    AKK_BANK_ORDER.forEach((bankKey, i) => {
      banks[bankKey] = buildAkkRowValues(rows, row + 1 + i, reliableCount);
    });

    const entry = { name, cat, grade, values, banks };
    if (AGG_NAMES.has(name)) aggs.push({ ...entry, agg: true });
    else cities.push(entry);

    row += AKK_BLOCK_SIZE;
  }

  return { months, aggs, cities, trimmedCount, trimmedFrom: trimmedCount > 0 ? monthsRaw[reliableCount] : null };
}

/* ---------------------------------------------------------------------- */
/* Загрузка данных из XLSX-файла, присланного пользователем через         */
/* /api/upload. Конвертируем лист в тот же формат "rows" (массив строк    */
/* текста), что и CSV-парсер — и переиспользуем buildMapData/buildAkkData/*/
/* buildErFullData без изменений.                                        */
/* ---------------------------------------------------------------------- */
function xlsxSheetToRows(ws) {
  if (!ws || !ws['!ref']) return [];
  const range = XLSX.utils.decode_range(ws['!ref']);
  const rows = [];
  for (let r = range.s.r; r <= range.e.r; r++) {
    const row = [];
    for (let c = range.s.c; c <= range.e.c; c++) {
      const addr = XLSX.utils.encode_cell({ r, c });
      const cell = ws[addr];
      if (!cell) { row.push(''); continue; }
      // .w — отформатированное отображаемое значение (как в CSV-экспорте:
      // "54,14%", "3 258 000"); если его нет — берём сырое значение .v
      row.push(cell.w !== undefined ? cell.w : (cell.v ?? ''));
    }
    rows.push(row);
  }
  return rows;
}

function findSheet(workbook, candidates) {
  const names = workbook.SheetNames;
  for (const want of candidates) {
    const found = names.find((n) => n.trim().toLowerCase() === want.toLowerCase());
    if (found) return found;
  }
  return null;
}

export async function applyUploadedWorkbook(buffer, fileName) {
  const workbook = XLSX.read(buffer, { type: 'buffer' });

  const sheetErFull = findSheet(workbook, ['Свод ЭР']);
  const sheetDomklik = findSheet(workbook, ['ДомКлик']);
  const sheetAkk = findSheet(workbook, ['Свод АКК']);
  const sheetCalc = findSheet(workbook, ['Калькулятор']);

  const services = [];
  let erData = null;

  if (sheetErFull) {
    const rows = xlsxSheetToRows(workbook.Sheets[sheetErFull]);
    erData = buildErFullData(rows);
    const network = erData.aggs.find((a) => a.city === 'Вся сеть');
    const dkMonths = erData.months.filter((m, i) => network && network.domklik[i] > 0);
    services.push({
      service: 'ЭР (Наша база)',
      sheet: sheetErFull,
      monthFrom: erData.months[0] || null,
      monthTo: erData.months[erData.months.length - 1] || null,
      monthCount: erData.months.length,
      citiesCount: erData.cities.length,
    });
    services.push({
      service: 'Дом Клик (конкурент)',
      sheet: sheetErFull,
      monthFrom: dkMonths[0] || null,
      monthTo: dkMonths[dkMonths.length - 1] || null,
      monthCount: dkMonths.length,
      citiesCount: erData.cities.length,
      note: dkMonths.length < erData.months.length ? 'данные по конкуренту есть не за весь период' : undefined,
    });
  } else if (sheetDomklik) {
    const rows = xlsxSheetToRows(workbook.Sheets[sheetDomklik]);
    const map = buildMapData(rows);
    erData = map;
    services.push({
      service: 'ЭР (Наша база)',
      sheet: sheetDomklik,
      monthFrom: map.months[0] || null,
      monthTo: map.months[map.months.length - 1] || null,
      monthCount: map.months.length,
      citiesCount: map.cities.length,
      note: 'лист "Свод ЭР" не найден в файле — использован укороченный лист "ДомКлик"',
    });
    services.push({
      service: 'Дом Клик (конкурент)',
      sheet: sheetDomklik,
      monthFrom: map.months[0] || null,
      monthTo: map.months[map.months.length - 1] || null,
      monthCount: map.months.length,
      citiesCount: map.cities.length,
    });
  } else {
    services.push({ service: 'ЭР (Наша база)', found: false, note: 'не найден лист "Свод ЭР" или "ДомКлик"' });
    services.push({ service: 'Дом Клик (конкурент)', found: false, note: 'не найден лист "Свод ЭР" или "ДомКлик"' });
  }

  let akkData = null;
  if (sheetAkk) {
    const rows = xlsxSheetToRows(workbook.Sheets[sheetAkk]);
    akkData = buildAkkData(rows);
    services.push({
      service: 'АКК (аккредитивы)',
      sheet: sheetAkk,
      monthFrom: akkData.months[0] || null,
      monthTo: akkData.months[akkData.months.length - 1] || null,
      monthCount: akkData.months.length,
      citiesCount: akkData.cities.length,
      note: akkData.trimmedCount > 0
        ? `в источнике обрезано ${akkData.trimmedCount} подозрительных мес. с ${akkData.trimmedFrom} (дублирующиеся значения — похоже на битую формулу)`
        : undefined,
    });
  } else {
    services.push({ service: 'АКК (аккредитивы)', found: false, note: 'лист "Свод АКК" не найден в файле' });
  }

  let calcData = null;
  if (sheetCalc) {
    const rows = xlsxSheetToRows(workbook.Sheets[sheetCalc]);
    calcData = buildCalcData(rows);
    services.push({
      service: 'Калькулятор АКК по чекам',
      sheet: sheetCalc,
      city: calcData.city,
      period: calcData.period,
    });
  } else {
    services.push({ service: 'Калькулятор АКК по чекам', found: false, note: 'лист "Калькулятор" не найден в этом файле (обычно это отдельная таблица)' });
  }

  if (!erData && !akkData && !calcData) {
    throw new Error('В файле не найдено ни одного распознаваемого листа ("Свод ЭР", "ДомКлик", "Свод АКК", "Калькулятор")');
  }

  const base = memCache || DEFAULT_DATA;
  const newData = {
    generatedAt: Date.now(),
    source: 'upload',
    sourceFile: fileName,
    months: erData ? erData.months : base.months,
    aggs: erData ? erData.aggs : base.aggs,
    cities: erData ? erData.cities : base.cities,
    calc: calcData || base.calc,
    akk: akkData || base.akk,
  };
  memCache = newData;
  saveDiskCache(newData);

  return { fileName, sheetsFound: workbook.SheetNames, services, data: newData };
}

/* ---------------------------------------------------------------------- */
/* Загрузка "вживую" + кэш (память + диск) + фоновое обновление           */
/* ---------------------------------------------------------------------- */
async function fetchLive() {
  const [mapRows, calcRows, akkRows] = await Promise.all([
    fetchCsv(SHEET_MAP), fetchCsv(SHEET_CALC), fetchCsv(SHEET_AKK),
  ]);
  const map = buildMapData(mapRows);
  const calc = buildCalcData(calcRows);
  const akk = buildAkkData(akkRows);
  if (akk.trimmedCount > 0) {
    console.warn(`Свод АКК: обрезан подозрительный хвост из ${akk.trimmedCount} мес. (начиная с ${akk.trimmedFrom}) — данные там дублируют более ранний период`);
  }
  return {
    generatedAt: Date.now(),
    source: 'live',
    months: map.months,
    aggs: map.aggs,
    cities: map.cities,
    calc,
    akk,
  };
}

function loadDiskCache() {
  try {
    if (!fs.existsSync(CACHE_FILE)) return null;
    const raw = fs.readFileSync(CACHE_FILE, 'utf8');
    return JSON.parse(raw);
  } catch {
    return null;
  }
}
function saveDiskCache(data) {
  try {
    fs.mkdirSync(path.dirname(CACHE_FILE), { recursive: true });
    fs.writeFileSync(CACHE_FILE, JSON.stringify(data), 'utf8');
  } catch (e) {
    console.warn('Не удалось сохранить кэш на диск:', e.message);
  }
}

let memCache = null;
let refreshInFlight = null;

export async function refreshData() {
  if (refreshInFlight) return refreshInFlight; // не дублируем параллельные запросы
  refreshInFlight = (async () => {
    const data = await fetchLive();
    memCache = data;
    saveDiskCache(data);
    return data;
  })();
  try {
    return await refreshInFlight;
  } finally {
    refreshInFlight = null;
  }
}

export async function getData() {
  if (memCache) {
    if (Date.now() - memCache.generatedAt > CACHE_TTL_MS) {
      refreshData().catch((e) => console.warn('Фоновое обновление не удалось:', e.message));
    }
    return memCache;
  }
  const disk = loadDiskCache();
  if (disk) {
    memCache = disk;
    if (Date.now() - disk.generatedAt > CACHE_TTL_MS) {
      refreshData().catch((e) => console.warn('Фоновое обновление не удалось:', e.message));
    }
    return memCache;
  }
  try {
    return await refreshData();
  } catch (e) {
    console.warn('Первая загрузка из Google Sheets не удалась, используем резервный снимок:', e.message);
    memCache = { ...DEFAULT_DATA, generatedAt: Date.now(), source: 'fallback' };
    return memCache;
  }
}

// Проверяем раз в час, обновляем, если кэшу больше 24 часов —
// так дашборд освежается сам, даже если на сайт никто не заходит.
export function startScheduler() {
  setInterval(() => {
    if (!memCache || Date.now() - memCache.generatedAt > CACHE_TTL_MS) {
      refreshData().catch((e) => console.warn('Плановое обновление не удалось:', e.message));
    }
  }, 60 * 60 * 1000);
}
